+      );
+      expect(
+        streamJsonEventLine(const TurnStartEvent()),
+        '{"type":"turn_start"}',
+      );
+      expect(
+        streamJsonEventLine(const AgentSettledEvent()),
+        '{"type":"agent_settled"}',
+      );
+    });
+
+    test('message_start / message_end carry the full message', () {
