+/// riding the stream byte-identically.
+void main() {
+  late MemoryExecutionEnv env;
+  late FakeCliIO io;
+
+  setUp(() {
+    env = MemoryExecutionEnv(cwd: '/work');
+    io = FakeCliIO();
+  });
