+      final stream = FakeStreamFunction([
+        toolTurn([
+          const ToolCall(id: 't1', name: 'read', arguments: {'path': 'a.txt'}),
+        ]),
+        textTurn('done'),
+      ]);
+      final (cli, lines) = cliWithStream(stream);
