+        ['--output-format', 'stream-json', '--prompt-file', 'p.md'],
+        ['--output-format', 'stream-json', 'hi'],
+      ]) {
+        final parsed = parseCliArgs(args) as CliArgs;
+        expect(parsed.outputFormat, 'stream-json', reason: '$args');
+      }
