+      expect(inner['type'], 'text_delta');
+      expect(inner['contentIndex'], 0);
+      expect(inner['delta'], 'Hi');
+    });
+
+    test('assembling text deltas reproduces message_end text (property)', () {
+      final fullText = 'stream-json keeps the wire linear';
