+      expect(
+        types,
+        containsAllInOrder([
+          'session',
+          'agent_start',
+          'turn_start',
+          'message_start',
+          'message_update',
+          'message_end',
+          'turn_end',
+          'agent_end',
+          'agent_settled',
+        ]),
+      );
+      // The streamed text assembled from deltas matches the final message.
+      final assembled = [
