+        streamJson: StreamJsonWriter(emit: lines.add),
+      );
+      expect(streamCode, textCode);
+      expect(streamCode, 1);
+      // E1: the error run still ends with agent_end + agent_settled, never
+      // a truncated line.
+      final types = [for (final e in parseLines(lines)) e['type'] as String];
