+        lines,
+      ).lastWhere((e) => e['type'] == 'turn_end');
+      expect((turnEnd['message'] as Map)['stopReason'], 'error');
+    },
+  );
+
+  test(
+    'tool round trip: start (with args) precedes end (with result) (AC4)',
+    timeout: const Timeout(Duration(seconds: 120)),
+    () async {
