+    api: 'test-api',
+    provider: 'test-provider',
+    model: 'test-model',
+    usage: usage,
+    stopReason: stopReason,
+    timestamp: DateTime.utc(2026),
+  );
+
+  group('streamJsonSessionHeaderLine', () {
+    test('first-line shape: session/version/id/timestamp/cwd', () {
+      final line = streamJsonSessionHeaderLine(
