+        output: 3,
+        cacheRead: 0,
+        cacheWrite: 0,
+        totalTokens: 10,
+        cost: UsageCost(),
+      );
+      final partial = assistant(usage: usage);
+      final event = MessageUpdateEvent(
+        message: partial,
+        assistantMessageEvent: TextDeltaEvent(
+          contentIndex: 0,
+          delta: 'Hi',
