  AfterToolCallResult? afterToolCall(
    AfterToolCallContext context,
    CancelToken? cancelToken,
  ) {
    final toolName = context.toolCall.name;
    if (isRedactionExemptTool(toolName) || !policy.appliesTo(toolName)) {
      return null;
