      return _redactToolResult(pipeline, message, policy);
    case AssistantMessage():
      final (blocks, changed) = _redactBlocks(pipeline, message.content, null);
      return changed ? message.copyWith(content: blocks) : message;
    default:
      return message;
  }
}

