+      final failing = AssistantMessage(
+        content: const [],
+        api: 'test-api',
+        provider: 'test-provider',
+        model: 'test-model',
+        usage: Usage.zero,
+        stopReason: StopReason.error,
+        errorMessage: 'boom',
+        timestamp: DateTime.utc(2026),
+      );
+      final failTurns = [
+        [ErrorEvent(reason: StopReason.error, error: failing)],
+      ];
