+      ];
+
+      final textCli = buildCli(FakeStreamFunction(failTurns));
+      final textCode = await textCli.runHeadless('hi');
+
+      final lines = <String>[];
+      final streamCli = buildCli(FakeStreamFunction(failTurns));
