+        timestamp: DateTime.utc(2026, 1, 2, 3, 4, 5),
+      );
+      final json = jsonDecode(line) as Map<String, dynamic>;
+      expect(json['type'], 'session');
+      expect(json['version'], 1);
+      expect(json['id'], 'sess-1');
