+  Future<void> _writeHeadlessEventHeaders({
+    HepWriter? hep,
+    StreamJsonWriter? streamJson,
+  }) async {
+    if (hep == null && streamJson == null) return;
+    final sessionId = _session!.cachedId ?? (await _session!.getMetadata()).id;
+    hep?.writeHeader(sessionId: sessionId);
